create table audit_logs (timestamp timestamp(6) with time zone not null, id uuid not null, action varchar(100) not null, target_id varchar(100), target_type varchar(100) not null, details TEXT, user_id varchar(255), primary key (id));
create table comments (score integer not null, created_at timestamp(6), updated_at timestamp(6), author_id uuid not null, entity_id uuid not null, id uuid not null, parent_comment_id uuid, content TEXT not null, entity_type varchar(255) not null, primary key (id));
create table discussions (comments_count integer not null, latitude float(53), longitude float(53), participant_count integer not null, proposal_count integer not null, votes_count integer not null, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, author_id uuid not null, id uuid not null, proposal_badge_variant varchar(20), category varchar(50) not null, gov_level varchar(50), proposal_badge varchar(50), location varchar(150), description TEXT not null, metadata TEXT, proposal_preview TEXT, title varchar(255) not null, primary key (id));
create table follows (created_at timestamp(6), follower_id uuid not null, id uuid not null, target_id uuid not null, target_type varchar(255) not null, primary key (id), unique (follower_id, target_type, target_id));
create table issues (comments_count integer not null, latitude float(53), longitude float(53), supports_count integer not null, workflow_step integer not null, created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, author_id uuid not null, id uuid not null, priority varchar(20) not null, status varchar(20) not null, category varchar(50) not null, gov_level varchar(50), location varchar(150), description TEXT not null, metadata TEXT, title varchar(255) not null, primary key (id));
create table notifications (is_read boolean not null, created_at timestamp(6), actor_id uuid, entity_id uuid, id uuid not null, recipient_id uuid not null, type varchar(255) not null, primary key (id));
create table polls (comments_count integer not null, latitude float(53), longitude float(53), votes_count integer not null, created_at timestamp(6) with time zone not null, expires_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, author_id uuid not null, id uuid not null, category varchar(50) not null, gov_level varchar(50), location varchar(150), description TEXT not null, metadata TEXT, options_json TEXT, question varchar(255) not null, primary key (id));
create table users (onboarding_completed boolean not null, privacy_consent_given boolean not null, reputation_score integer not null, grace_period_ends_at timestamp(6) with time zone, joined_date timestamp(6) with time zone not null, privacy_consent_timestamp timestamp(6) with time zone, subscription_ends_at timestamp(6) with time zone, id uuid not null, dob varchar(20), gender varchar(20), phone_number varchar(20), pincode varchar(20), role varchar(20) not null, subscription_status varchar(20) not null, city varchar(50), country varchar(50), district varchar(50), provider varchar(50) not null, state varchar(50), constituency varchar(100), locality varchar(100), name varchar(100) not null, occupation varchar(100), ward varchar(100), location varchar(150), bio varchar(1000), topics varchar(1000), email varchar(255) not null unique, provider_id varchar(255) not null, primary key (id), unique (provider, provider_id));
create table votes (vote_value integer not null, entity_id uuid not null, id uuid not null, user_id uuid not null, entity_type varchar(255) not null, primary key (id), unique (user_id, entity_type, entity_id));
create index idx_issues_jurisdiction on issues (location);
create index idx_issues_status on issues (status);
