alter table if exists issues add constraint fk_issues_author foreign key (author_id) references users;
alter table if exists notifications add constraint FK4sd9fik0uthbk6d9rsxco4uja foreign key (actor_id) references users;
alter table if exists notifications add constraint FKqqnsjxlwleyjbxlmm213jaj3f foreign key (recipient_id) references users;
alter table if exists polls add constraint fk_polls_author foreign key (author_id) references users;
alter table if exists votes add constraint FKli4uj3ic2vypf5pialchj925e foreign key (user_id) references users;
